ruleContent.content:
@css:div.field--name-body@html
<js>
if (!result || !result.trim()) {
  result = '';
}
result = result.replace(/src="\/sites\//g, 'src="https://www.usni.org/sites/');
result = result.replace(/href="\/magazines\//g, 'href="https://www.usni.org/magazines/');
result = result.replace(/href="\/sites\//g, 'href="https://www.usni.org/sites/');
result;
</js>
